-- composition of rule kernels aggregate_function_rewriter x window_self_join (duckdb), template not_exists
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 100.0::float8 AS c1, '0'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, 100.0::float8 AS c1, MAX ('-1 month'::interval) OVER () AS c2 FROM tp AS a1) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT a1.c0 AS c0, a1.c0 AS c1, AVG (41) AS c2, AVG ((-1.5)::float8) AS c3 FROM t0 AS a1 GROUP BY a1.c0) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT a1.c0 AS c0, a1.c0 AS c1, AVG (41) AS c2, AVG ((-1.5)::float8) AS c3 FROM t0 AS a1 GROUP BY a1.c0) AS kb) = 0 THEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 100.0::float8 AS c1, '0'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, 100.0::float8 AS c1, MAX ('-1 month'::interval) OVER () AS c2 FROM tp AS a1) AS ka) ELSE 0 END
